script.text:
			/* <flatten type="Javascript"> */
function load$GridSalesEmployee(g) {
	g.add_onResponseComplete(on$GridSalesEmployee$ResponseComplete);
	g.add_commandEvent(on$GridSalesEmployee$ExecuteCommand);
	g.add_onRender(on$GridSalesEmployee$GridRender);
}
function dispose$GridSalesEmployee(g) {
	try {g.remove_commandEvent(on$GridSalesEmployee$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridSalesEmployee$ResponseComplete);} catch (ex) {}
	try {g.remove_onRender(on$GridSalesEmployee$GridRender);} catch (ex) {}
}
function on$GridSalesEmployee$GridRender(sender, eventArgs) {
	var g = eventArgs.grid;
	if (g._extensions && g._rowCount == 1) {
		g._setActiveCell(g._getItem(1, 1));
		g.executeCommand({commandName:'View',commandArgument:'0'})
	}
}
/* </flatten> */
function on$GridSalesEmployee$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender;
	switch (action) {
		case 'ImportData':
			show$Form(g, 'SalesEmployeeImport');
			break;
		case 'Download':
			&UserDefinedDownload;
			break;
		default:
			break;
	}
}
/* <flatten type="Javascript"> */
function on$GridSalesEmployee$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object;
	switch (context) {
		case 'Download':
			g._key = result[0].Value;
			break;
		default:
			break;
	}
}
function show$Form(g, c) {(g._authorize == 1) ? g.showForm(c) : $message.show($df.getResources(g._language, "Message.NotAccess"));}
/* </flatten> */
			&DowloadScript;
